from core import *
ar('total','Sum an array','Print the sum of every element; an empty array sums to zero.',lambda a,t:sum(a),'long v=0;for(long x:a)v+=x;return ""+v;')
ar('minimum','Minimum value','Print the minimum value, or EMPTY if n=0.',lambda a,t:min(a) if a else 'EMPTY','if(a.length==0)return "EMPTY";long v=a[0];for(long x:a)v=Math.min(v,x);return ""+v;')
ar('reverse','Reverse the sequence','Print all elements in reverse order. Aim for constant auxiliary space beyond the input.',lambda a,t:a[::-1],'for(int l=0,r=a.length-1;l<r;l++,r--){long v=a[l];a[l]=a[r];a[r]=v;}return fmt(a);')
ar('odd','Keep odd values','Print odd elements in their original order. Negative odd values must be retained.',lambda a,t:[x for x in a if x%2],'List<Long> out=new ArrayList<>();for(long x:a)if(x%2!=0)out.add(x);return fmt(out);')
ar('signcounts','Count value categories','Print the counts of negative, zero, and positive elements, in that order.',lambda a,t:[sum(x<0 for x in a),a.count(0),sum(x>0 for x in a)],'int neg=0,zero=0,pos=0;for(long x:a){if(x<0)neg++;else if(x==0)zero++;else pos++;}return neg+" "+zero+" "+pos;')
ar('second','Second distinct largest','Print the second largest distinct value, or NONE if fewer than two distinct values exist.',lambda a,t:sorted(set(a))[-2] if len(set(a))>1 else 'NONE','TreeSet<Long> set=new TreeSet<>();for(long x:a)set.add(x);if(set.size()<2)return "NONE";set.pollLast();return ""+set.last();')
ar('sorted','Check nondecreasing order','Print true if each element is at least its predecessor. Empty and one-element arrays are sorted.',lambda a,t:a==sorted(a),'for(int i=1;i<a.length;i++)if(a[i]<a[i-1])return "false";return "true";')
ar('uniqueorder','Remove repeated values','Print one occurrence of each value, preserving its first appearance.',lambda a,t:list(dict.fromkeys(a)),'Set<Long> set=new LinkedHashSet<>();for(long x:a)set.add(x);return fmt(set);')
ar('zeros','Move zeros to the end','Move all zero values to the end while preserving the order of nonzero values. Do this in place.',lambda a,t:[x for x in a if x]+[0]*a.count(0),'int j=0;for(long x:a)if(x!=0)a[j++]=x;while(j<a.length)a[j++]=0;return fmt(a);')
ar('rotate','Rotate right by k','Read a nonnegative k after the array. Rotate the array right by k positions; handle k≥n and n=0.',lambda a,t:a[-(t[0]%len(a)):]+a[:-(t[0]%len(a))] if a and t[0]%len(a) else a,'int k=s.nextInt();if(a.length==0)return "EMPTY";long[] b=new long[a.length];for(int i=0;i<a.length;i++)b[(i+k%a.length)%a.length]=a[i];return fmt(b);',[arr(a,[k]) for a,k in [([1,2,3,4],1),([3,2,1],5),([],9),([4],1000),([2,2,0],0)]],extra=' Then read k (0≤k≤1,000,000).',hint='Reduce k modulo n only after handling an empty array. Reverse sections or map each old index to its new position.')
ar('prefix','Build prefix totals','Print the sum of elements from index 0 through each index. Use long for cumulative totals.',lambda a,t:list(itertools.accumulate(a)),'long v=0;for(int i=0;i<a.length;i++){v+=a[i];a[i]=v;}return fmt(a);')
ar('suffix','Build suffix totals','For each index i, print the sum of a[i] through a[n−1], in original index order.',lambda a,t:[sum(a[i:]) for i in range(len(a))],'long v=0;for(int i=a.length-1;i>=0;i--){v+=a[i];a[i]=v;}return fmt(a);')
ar('equilibrium','First balance index','Print the first zero-based index where the sum strictly to its left equals the sum strictly to its right. Print −1 if none.',lambda a,t:next((i for i in range(len(a)) if sum(a[:i])==sum(a[i+1:])),-1),'long total=0,left=0;for(long x:a)total+=x;for(int i=0;i<a.length;i++){if(left==total-left-a[i])return ""+i;left+=a[i];}return "-1";',arrays=[[1,3,5,2,2],[],[0],[1,2,3],[-1,0,-1],[0,0]])
ar('kadane','Maximum nonempty subarray sum','For n≥1, print the maximum sum of a contiguous nonempty subarray. All-negative inputs are valid.',lambda a,t:max(sum(a[i:j]) for i in range(len(a)) for j in range(i+1,len(a)+1)),'long best=a[0],end=a[0];for(int i=1;i<a.length;i++){end=Math.max(a[i],end+a[i]);best=Math.max(best,end);}return ""+best;',arrays=[[2,-3,4,-1,2],[-4,-1,-7],[0],[9],[1,-1,1,-1,1]],bounds=['1≤n≤1,000','−1,000,000≤a[i]≤1,000,000'],hint='Track the best sum ending here. Decide whether extending the previous range is better than starting here.')
ar('leaders','Find array leaders','A leader is strictly larger than every value to its right. Print leaders in original order. The last element is always a leader.',lambda a,t:[x for i,x in enumerate(a) if all(x>v for v in a[i+1:])],'List<Long> out=new ArrayList<>();long best=Long.MIN_VALUE;for(int i=a.length-1;i>=0;i--)if(a[i]>best){best=a[i];out.add(a[i]);}Collections.reverse(out);return fmt(out);')
ar('productexcept','Product except self','For each index, print the product of every other element. Do not divide. An empty product is 1.',lambda a,t:[math.prod(a[:i]+a[i+1:]) for i in range(len(a))],'long[] out=new long[a.length];long p=1;for(int i=0;i<a.length;i++){out[i]=p;p*=a[i];}p=1;for(int i=a.length-1;i>=0;i--){out[i]*=p;p*=a[i];}return fmt(out);',arrays=[[1,2,3,4],[0,2,3],[0,0,3],[-1,2,-3],[5],[]],bounds=['0≤n≤12','−10≤a[i]≤10','All intermediate products fit in long.'])
ar('paircount','Count pairs with target sum','Read target t after the array. Count index pairs i<j with a[i]+a[j]=t. Repeated values represent different indices.',lambda a,t:sum(a[i]+a[j]==t[0] for i in range(len(a)) for j in range(i+1,len(a))),'long target=s.nextLong(),count=0;Map<Long,Long> f=new HashMap<>();for(long x:a){count+=f.getOrDefault(target-x,0L);f.merge(x,1L,Long::sum);}return ""+count;',[arr(a,[k]) for a,k in [([1,2,3,2],4),([0,0,0],0),([],4),([-1,1,2,-2],0),([7],14)]],extra=' Then read target t (|t|≤2,000,000).')
ar('subsum','Count subarrays with target sum','Read target t after the array. Count nonempty contiguous subarrays with sum t. Negative numbers are allowed.',lambda a,t:sum(sum(a[i:j])==t[0] for i in range(len(a)) for j in range(i+1,len(a)+1)),'long t=s.nextLong(),p=0,count=0;Map<Long,Long> f=new HashMap<>();f.put(0L,1L);for(long x:a){p+=x;count+=f.getOrDefault(p-t,0L);f.merge(p,1L,Long::sum);}return ""+count;',[arr(a,[k]) for a,k in [([1,1,1],2),([1,-1,0],0),([],0),([0,0,0],0),([5,-2,3],3)]],extra=' Then read target t (|t|≤1,000,000).',hint='Express each range sum as the difference of two prefix totals. Count earlier prefixes with the required difference.')
ar('longzero','Longest zero-sum range','Print the length of the longest contiguous range summing to zero. Print 0 if no such nonempty range exists.',lambda a,t:max([0]+[j-i for i in range(len(a)) for j in range(i+1,len(a)+1) if sum(a[i:j])==0]),'Map<Long,Integer> first=new HashMap<>();first.put(0L,-1);long p=0;int best=0;for(int i=0;i<a.length;i++){p+=a[i];if(first.containsKey(p))best=Math.max(best,i-first.get(p));else first.put(p,i);}return ""+best;')
ar('distinct','Count distinct values','Print the number of distinct array values.',lambda a,t:len(set(a)),'Set<Long> set=new HashSet<>();for(long x:a)set.add(x);return ""+set.size();')
ar('mode','Most frequent value','Print the value with greatest frequency; ties choose the smallest value. Print EMPTY for n=0.',lambda a,t:min(set(a),key=lambda x:(-a.count(x),x)) if a else 'EMPTY','if(a.length==0)return "EMPTY";Map<Long,Integer> f=new TreeMap<>();for(long x:a)f.merge(x,1,Integer::sum);long best=0;int count=0;for(var e:f.entrySet())if(e.getValue()>count){best=e.getKey();count=e.getValue();}return ""+best;')
ar('firstunique','First nonrepeated value','Print the first value in input order occurring exactly once, or NONE.',lambda a,t:next((x for x in a if a.count(x)==1),'NONE'),'Map<Long,Integer> f=new HashMap<>();for(long x:a)f.merge(x,1,Integer::sum);for(long x:a)if(f.get(x)==1)return ""+x;return "NONE";')
ar('majority','Find a strict majority','Print the value occurring more than n/2 times, or NONE. Verify any candidate.',lambda a,t:next((x for x in a if a.count(x)>len(a)//2),'NONE'),'long candidate=0;int balance=0,count=0;for(long x:a){if(balance==0)candidate=x;balance+=x==candidate?1:-1;}for(long x:a)if(x==candidate)count++;return count>a.length/2?""+candidate:"NONE";',arrays=[[2,2,1,2],[1,2,3],[],[5],[0,0,-1,-1,0]])
ar('consecutive','Longest consecutive set','Print the longest run of consecutive integer values present, regardless of original order. Duplicates do not extend a run.',lambda a,t:max([0]+[next((k for k in range(1,len(a)+2) if x+k not in a),len(a)+1) for x in set(a)]),'Set<Long> set=new HashSet<>();for(long x:a)set.add(x);int best=0;for(long x:set)if(!set.contains(x-1)){int len=1;while(set.contains(x+len))len++;best=Math.max(best,len);}return ""+best;',arrays=[[100,4,200,1,3,2],[0,-1,1,1],[],[8],[5,5,5]])
ar('sortdesc','Sort descending','Print all elements in descending order, retaining duplicates.',lambda a,t:sorted(a,reverse=True),'Arrays.sort(a);List<Long> b=new ArrayList<>();for(int i=a.length-1;i>=0;i--)b.add(a[i]);return fmt(b);')
ar('squares','Sorted squares','The input is sorted nondecreasingly. Print its squares in nondecreasing order. Target O(n) time with two pointers.',lambda a,t:sorted(x*x for x in a),'long[] b=new long[a.length];int l=0,r=a.length-1;for(int i=a.length-1;i>=0;i--){if(Math.abs(a[l])>Math.abs(a[r])){b[i]=a[l]*a[l];l++;}else{b[i]=a[r]*a[r];r--;}}return fmt(b);',arrays=[[-5,-1,0,3],[],[-2],[0,0,1],[-8,-4,-3]])
ar('inversions','Count inversions','Count pairs i<j where a[i]>a[j]. Aim for O(n log n) by augmenting merge sort; equal values do not form inversions.',lambda a,t:sum(a[i]>a[j] for i in range(len(a)) for j in range(i+1,len(a))),'return ""+inv(a,0,a.length);')
import core
core.JAVA_HELPERS += r'''
static long inv(long[] a,int lo,int hi){if(hi-lo<2)return 0;int m=(lo+hi)/2;long count=inv(a,lo,m)+inv(a,m,hi);long[] b=new long[hi-lo];int i=lo,j=m,k=0;while(i<m||j<hi){if(j==hi||(i<m&&a[i]<=a[j]))b[k++]=a[i++];else{b[k++]=a[j++];count+=m-i;}}System.arraycopy(b,0,a,lo,b.length);return count;}
'''
ar('stock','Best single trade','Prices are nonnegative. Buy once before selling once; you may choose no trade. Print maximum profit.',lambda a,t:max([0]+[a[j]-a[i] for i in range(len(a)) for j in range(i+1,len(a))]),'long low=Long.MAX_VALUE,best=0;for(long x:a){low=Math.min(low,x);best=Math.max(best,x-low);}return ""+best;',arrays=[[7,1,5,3,6,4],[9,7,4],[],[2],[1,2,3]],bounds=['0≤n≤1,000','0≤price≤1,000,000'])
ar('water','Trapped rainwater','Nonnegative heights form unit-width bars. Print total water trapped after rain.',lambda a,t:sum(max(0,min(max(a[:i+1]),max(a[i:]))-a[i]) for i in range(len(a))),'if(a.length==0)return "0";long left=0,right=0,total=0;int l=0,r=a.length-1;while(l<=r){if(a[l]<=a[r]){left=Math.max(left,a[l]);total+=left-a[l++];}else{right=Math.max(right,a[r]);total+=right-a[r--];}}return ""+total;',arrays=[[3,0,2,0,4],[2,1,2],[],[4],[0,1,2,3]],bounds=['0≤n≤1,000','0≤height≤1,000,000'])
ar('nextgreater','Next strictly greater value','For every element, print the first greater value strictly to its right, or NONE. Output n tokens; print EMPTY for n=0.',lambda a,t:[next((y for y in a[i+1:] if y>x),'NONE') for i,x in enumerate(a)],'String[] out=new String[a.length];Deque<Long> q=new ArrayDeque<>();for(int i=a.length-1;i>=0;i--){while(!q.isEmpty()&&q.peek()<=a[i])q.pop();out[i]=q.isEmpty()?"NONE":""+q.peek();q.push(a[i]);}return a.length==0?"EMPTY":String.join(" ",out);')
ar('span','Stock span','For each day, count the consecutive days ending today with values ≤ today’s value, including today.',lambda a,t:[next((k for k in range(1,i+2) if k==i+1 or a[i-k]>x),i+1) for i,x in enumerate(a)],'long[] out=new long[a.length];Deque<Integer> st=new ArrayDeque<>();for(int i=0;i<a.length;i++){while(!st.isEmpty()&&a[st.peek()]<=a[i])st.pop();out[i]=st.isEmpty()?i+1:i-st.peek();st.push(i);}return fmt(out);')
ar('histogram','Largest histogram rectangle','Nonnegative heights form unit-width bars. Print the largest rectangle area that fits under consecutive bars.',lambda a,t:max([0]+[min(a[i:j])*(j-i) for i in range(len(a)) for j in range(i+1,len(a)+1)]),'long best=0;Deque<Integer> st=new ArrayDeque<>();for(int i=0;i<=a.length;i++){long x=i==a.length?0:a[i];while(!st.isEmpty()&&a[st.peek()]>=x){long h=a[st.pop()];int left=st.isEmpty()?0:st.peek()+1;best=Math.max(best,h*(i-left));}st.push(i);}return ""+best;',arrays=[[2,1,5,6,2,3],[2,2],[],[0],[4,3,2,1]],bounds=['0≤n≤1,000','0≤height≤1,000,000'])
ar('lowerbound','First value at least target','Input is sorted. Read t after the array; print the first index i with a[i]≥t, or n if none. Target O(log n).',lambda a,t:bisect.bisect_left(a,t[0]),'long t=s.nextLong();int l=0,r=a.length;while(l<r){int m=(l+r)/2;if(a[m]<t)l=m+1;else r=m;}return ""+l;',[arr(a,[t]) for a,t in [([1,3,3,8],3),([1,3],9),([],0),([5],1),([-4,-2,0],-3)]],extra=' Then read target t (|t|≤1,000,000).')
ar('upperbound','First value greater than target','Input is sorted. Read t; print the first index with a[i]>t, or n if none. Target O(log n).',lambda a,t:bisect.bisect_right(a,t[0]),'long t=s.nextLong();int l=0,r=a.length;while(l<r){int m=(l+r)/2;if(a[m]<=t)l=m+1;else r=m;}return ""+l;',[arr(a,[t]) for a,t in [([1,3,3,8],3),([1,3],9),([],0),([5],1),([-4,-2,0],-3)]],extra=' Then read target t (|t|≤1,000,000).')
ar('occurrences','Count target occurrences','Input is sorted. Read target t after the array. Count its occurrences using two binary searches.',lambda a,t:a.count(t[0]),'long t=s.nextLong();int l=0,r=a.length;while(l<r){int m=(l+r)/2;if(a[m]<t)l=m+1;else r=m;}int first=l;r=a.length;while(l<r){int m=(l+r)/2;if(a[m]<=t)l=m+1;else r=m;}return ""+(l-first);',[arr(a,[t]) for a,t in [([1,3,3,3,8],3),([1,3],2),([],0),([5],5),([2,2,2],2)]],extra=' Then read target t (|t|≤1,000,000).')
for key,title,op,body in [
 ('windowmin','Minimum of every window',min,'while(!q.isEmpty()&&a[q.peekLast()]>=a[i])q.pollLast();'),
 ('windowmax','Maximum of every window',max,'while(!q.isEmpty()&&a[q.peekLast()]<=a[i])q.pollLast();')]:
 ar(key,title,'Read window size k. Print the '+('minimum' if key=='windowmin' else 'maximum')+' of each contiguous window, left to right. Use a monotonic deque for O(n) time.',lambda a,t,op=op:[op(a[i:i+t[0]]) for i in range(len(a)-t[0]+1)],'int k=s.nextInt();List<Long> out=new ArrayList<>();Deque<Integer> q=new ArrayDeque<>();for(int i=0;i<a.length;i++){while(!q.isEmpty()&&q.peekFirst()<=i-k)q.pollFirst();'+body+'q.offerLast(i);if(i>=k-1)out.add(a[q.peekFirst()]);}return fmt(out);',[arr(a,[k]) for a,k in [([2,1,5,3,4],3),([-3,-1,-2],2),([7],1),([2,2,2],3),([4,2,6],1)]],extra=' Then read k.',bounds=['1≤n≤1,000','1≤k≤n','|a[i]|≤1,000,000'])
ar('windowdistinct','Distinct values in every window','Read k. Print the number of distinct values in each consecutive k-element window.',lambda a,t:[len(set(a[i:i+t[0]])) for i in range(len(a)-t[0]+1)],'int k=s.nextInt();Map<Long,Integer> f=new HashMap<>();List<Integer> out=new ArrayList<>();for(int i=0;i<a.length;i++){f.merge(a[i],1,Integer::sum);if(i>=k){long old=a[i-k];int c=f.get(old)-1;if(c==0)f.remove(old);else f.put(old,c);}if(i>=k-1)out.add(f.size());}return fmt(out);',[arr(a,[k]) for a,k in [([1,2,1,3,4],3),([2,2,2],2),([8],1),([-1,0,-1],3),([4,5,6],1)]],extra=' Then read k.',bounds=['1≤n≤1,000','1≤k≤n','|a[i]|≤1,000,000'])
ar('shortpositive','Shortest range reaching a target','All values are positive. Read positive target t. Print the minimum length of a contiguous range with sum≥t, or 0 if none.',lambda a,t:min([len(a)+1]+[j-i for i in range(len(a)) for j in range(i+1,len(a)+1) if sum(a[i:j])>=t[0]]) if sum(a)>=t[0] else 0,'long t=s.nextLong(),sum=0;int l=0,best=a.length+1;for(int r=0;r<a.length;r++){sum+=a[r];while(sum>=t){best=Math.min(best,r-l+1);sum-=a[l++];}}return ""+(best>a.length?0:best);',[arr(a,[t]) for a,t in [([2,3,1,2,4,3],7),([1,1],3),([],1),([9],5),([1,2,3],6)]],extra=' Then read target t.',bounds=['0≤n≤1,000','1≤a[i],t≤1,000,000'])
ar('circularsum','Maximum circular subarray sum','For a nonempty array, a range may wrap from the end to the beginning but use each index at most once. Print its largest nonempty sum.',lambda a,t:max(sum((a+a)[i:i+k]) for i in range(len(a)) for k in range(1,len(a)+1)),'long total=a[0],maxEnd=a[0],minEnd=a[0],mx=a[0],mn=a[0];for(int i=1;i<a.length;i++){total+=a[i];maxEnd=Math.max(a[i],maxEnd+a[i]);minEnd=Math.min(a[i],minEnd+a[i]);mx=Math.max(mx,maxEnd);mn=Math.min(mn,minEnd);}return ""+(mx<0?mx:Math.max(mx,total-mn));',arrays=[[5,-3,5],[-3,-2,-5],[1],[0,0],[3,-1,2,-1]],bounds=['1≤n≤1,000','|a[i]|≤1,000,000'])
ar('missingpositive','Smallest missing positive','Print the smallest positive integer absent from the array. Aim for O(n) time and O(1) auxiliary space by placing values at matching indices.',lambda a,t:next(x for x in range(1,len(a)+2) if x not in a),'for(int i=0;i<a.length;i++)while(a[i]>=1&&a[i]<=a.length&&a[(int)a[i]-1]!=a[i]){int j=(int)a[i]-1;long v=a[i];a[i]=a[j];a[j]=v;}for(int i=0;i<a.length;i++)if(a[i]!=i+1)return ""+(i+1);return ""+(a.length+1);',arrays=[[3,4,-1,1],[1,2,0],[],[1],[2,2,2]])
